exercises.code:
// Sin pool: crea y destruye un hilo nuevo por cada tarea (costoso)
new Thread(tarea).start();

// Con pool: reutiliza hilos ya creados
ExecutorService pool = Executors.newFixedThreadPool(4);
pool.execute(tarea);

Callable<Integer> tarea = () -> 10 + 20;
Future<Integer> resultado = pool.submit(tarea);
Integer valor = resultado.get(); // bloquea hasta que la tarea termine

ExecutorService pool = Executors.newSingleThreadExecutor();
Future<Integer> resultado = pool.submit(() -> 10 + 20);
System.out.println(resultado.get());
pool.shutdown();

ExecutorService pool = Executors.newFixedThreadPool(2);
pool.submit(() -> System.out.println("tarea"));
pool.shutdown(); // deja terminar las tareas ya enviadas (en curso o en cola), rechaza nuevas, y el programa puede salir

CompletableFuture<Integer> futuro = CompletableFuture.supplyAsync(() -> 5)
    .thenApply(n -> n * 2)
    .thenApply(n -> n + 1);
System.out.println(futuro.join());

// thenCompose: la segunda tarea NECESITA el resultado de la primera
CompletableFuture<Integer> dependiente = CompletableFuture.supplyAsync(() -> 5)
    .thenCompose(n -> CompletableFuture.supplyAsync(() -> n * 10));

// thenCombine: ambas tareas corren independientes, se combinan al final
CompletableFuture<Integer> a = CompletableFuture.supplyAsync(() -> 5);
CompletableFuture<Integer> b = CompletableFuture.supplyAsync(() -> 10);
CompletableFuture<Integer> combinado = a.thenCombine(b, (x, y) -> x + y);

