Semaphore semaforo = new Semaphore(3); // maximo 3 hilos a la vez

void usarRecurso() throws InterruptedException {
    semaforo.acquire(); // espera si ya hay 3 hilos dentro
    try {
        // seccion con hasta 3 hilos simultaneos permitidos
    } finally {
        semaforo.release();
    }
}

ReadWriteLock rwLock = new ReentrantReadWriteLock();

void leer() {
    rwLock.readLock().lock();
    try {
        // muchos hilos pueden ejecutar esto a la vez
    } finally {
        rwLock.readLock().unlock();
    }
}

void escribir() {
    rwLock.writeLock().lock();
    try {
        // solo un hilo, y ningun lector, puede ejecutar esto
    } finally {
        rwLock.writeLock().unlock();
    }
}

